// Saco la llamada del body y reviso que tenga transcripcion.
// Para practicar, la llamada llega como JSON escrito por nosotros.
let call = $json.body ?? $json;

if (typeof call === 'string') {
  try {
    call = JSON.parse(call);
  } catch (error) {
    call = {};
  }
}

const transcript = call.transcript ?? call.message ?? call.notes;
const missing = [];

if (!transcript) {
  missing.push('transcript');
}

return [{
  json: {
    ...call,
    is_valid: missing.length === 0,
    validation_status: missing.length === 0 ? 'valid' : 'invalid',
    missing_fields: missing,
    received_at: new Date().toISOString(),
  }
}];

// Preparo una notificacion interna para que el asesor sepa que debe devolver o continuar la llamada.
const voiceCall = $json.voice_call ?? {};
const message = voiceCall.advisor_brief ?? `Llamada para revisar: ${voiceCall.caller_name ?? 'cliente por confirmar'}`;

return [{
  json: {
    ...$json,
    advisor_message: message,
    priority: voiceCall.priority ?? 'medium',
    channel: 'advisor_inbox',
    lead: {
      id: voiceCall.id,
      quote_id: '',
      full_name: voiceCall.caller_name,
      phone: voiceCall.phone,
      priority: voiceCall.priority ?? 'medium',
      advisor_message: message,
    },
  }
}];
